import java.util.*;

class Solution {
    public int maxWindowSum(int[] nums, int k) {
        if (k <= 0 || nums.length == 0) return 0;
        int sum = 0;
        for (int i = 0; i < k && i < nums.length; i++) sum += nums[i];
        int best = sum;
        for (int i = k; i < nums.length; i++) {
            sum += nums[i] - nums[i - k];
            best = Math.max(best, sum);
        }
        return best;
    }
}
